import{_ as l,b as p,c as t,g as e}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"美国纽约摄影学院摄影教材","description":"","frontmatter":{"title":"美国纽约摄影学院摄影教材","subTitle":"好照片的标准与题材","author":"oasis","date":"2026-09-20T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/nyip-course/4.md","filePath":"articles/books/nyip-course/4.md"}'),a={name:"articles/books/nyip-course/4.md"};function d(o,i,n,s,h,r){return p(),t("div",null,[...i[0]||(i[0]=[e('<h2 id="好照片的标准" tabindex="-1">好照片的标准</h2><ol><li>清晰</li><li>曝光良好</li><li>色调范围：黑白照片应该有很宽的色域，从最黑到最白</li><li>反差</li></ol><p>彩色照片还应该具备：</p><ol><li>色彩逼真度</li><li>色彩饱和度</li><li>色彩平衡</li><li>色彩反差</li></ol><h2 id="怎么拍一个人" tabindex="-1">怎么拍一个人</h2><p>如何通过摄影表现一个人的特征、状态和性格。</p><h2 id="儿童摄影" tabindex="-1">儿童摄影</h2><p>捕捉瞬间。</p><h2 id="风景摄影" tabindex="-1">风景摄影</h2><p>如何建立空间感？</p><h2 id="建筑与室内摄影" tabindex="-1">建筑与室内摄影</h2><p>透视：如何把三维建筑准确地转换成二维画面。</p><h2 id="产品-静物摄影" tabindex="-1">产品 / 静物摄影</h2><p>光线到底改变了什么？反射、折射、高光、阴影、质感。</p><h2 id="人体魅态摄影" tabindex="-1">人体魅态摄影</h2><p>核心仍然是：如何通过光线、姿态、构图，把人体的形态表现出来。</p><h3 id="姿态" tabindex="-1">姿态</h3><p>人体摄影不是简单地让模特「站好」，而是利用身体的曲线、重心、四肢方向、身体扭转，形成视觉线条。</p><h3 id="光线" tabindex="-1">光线</h3><p>光线决定人体的立体感。例如：</p><ul><li>正面光 → 身体比较平</li><li>侧光 → 肌肉、曲线、凹凸更加明显</li><li>逆光 → 强调轮廓</li></ul><h2 id="广告摄影与静物摄影" tabindex="-1">广告摄影与静物摄影</h2><p>广告摄影到底拍什么？让观众产生购买或向往这个东西的欲望。</p><p>静物摄影的本质，是控制物体周围的光线，让物体呈现你想要的质感。</p><h2 id="建筑摄影" tabindex="-1">建筑摄影</h2><p>核心：如何控制「空间的形状」。</p><p>建筑摄影最大的敌人是透视。透视投影改变了三维空间在二维照片中的形状。</p><p>建筑摄影的核心不是把建筑拍全，而是控制照片中的空间和透视关系。</p><h2 id="新闻摄影" tabindex="-1">新闻摄影</h2><p>发生的事情中，什么最值得让别人知道？判断什么具有新闻价值。</p><p>优秀新闻照片通常同时解决两个问题：</p><ol><li>发生了什么？</li><li>为什么重要？</li></ol><p>比如一个人摔倒：</p><ul><li>普通照片：一个人躺在地上。</li><li>新闻照片：通过人物、环境、动作，让你知道「为什么他会在那里」。</li></ul><p>所以新闻摄影要求信息密度。</p>',35)])])}const b=l(a,[["render",d]]);export{c as __pageData,b as default};
